        long long chosenL = -1;
        for(long long L = 1; L <= remaining; L++){
            long long rem2 = remaining - L;
            long long cnt;
            if(rem2 == 0){
                cnt = 1;
            } else {
                // 2^(rem2-1)
                long long exp = rem2 - 1;
                cnt = 1LL << exp; // exp <= 48 for n<=50, safe
            }

            if(k <= cnt){
                chosenL = L;
                break;
            } else {
                k -= cnt;
            }
        }

        long long L = chosenL;
        // fill segment [pos, pos+L-1] reversed
        for(long long i = 0; i < L; i++){
            p[pos + i] = (int)(pos + L - 1 - i);
        }

        pos += L;
        remaining -= L;
    }

    for(int i = 1; i <= n; i++){
        cout << p[i];
        if(i < n) cout << " ";
