#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

vector<ll> genPow(ll base, ll limit){
    vector<ll> res;
    ll p = 1;
    res.push_back(p);
    while(true){
        if(p > limit / base) break;
        ll np = p * base;
        if(np > limit) break;
        p = np;
        res.push_back(p);
    }
    return res;
}

int main(){
    ll x, y, l, r;
    cin >> x >> y >> l >> r;

    vector<ll> Xp = genPow(x, r);
    vector<ll> Yp = genPow(y, r);

    vector<ll> sums;
    sums.reserve(Xp.size() * Yp.size());
    for(ll a : Xp){
        for(ll b : Yp){
            ll s = a + b;
            if(s <= r){
                sums.push_back(s);
            }
        }
    }

    sort(sums.begin(), sums.end());
    sums.erase(unique(sums.begin(), sums.end()), sums.end());

    ll prev = l - 1;
    ll best = 0;

    for(ll u : sums){
        if(u < l || u > r) continue;
        ll gap = u - prev - 1;
        if(gap > best) best = gap;
        prev = u;
    }

    ll tailGap = r - prev;
    if(tailGap > best) best = tailGap;

    cout << best << endl;

    return 0;
}
