#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007LL;

long long power_mod(long long base, long long exp, long long mod) {
    base %= mod;
    if (base < 0) base += mod;
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    long long x, n;
    cin >> x >> n;

    vector<long long> primes;
    long long temp = x;
    for (long long p = 2; p * p <= temp; ++p) {
        if (temp % p == 0) {
            primes.push_back(p);
            while (temp % p == 0) temp /= p;
        }
    }
    if (temp > 1) primes.push_back(temp);

    long long answer = 1;

    for (long long p : primes) {
        long long S = 0;
        long long cur = p;
        while (cur <= n) {
            S += n / cur;
            if (cur > n / p) break; // prevent overflow
            cur *= p;
        }
        long long exponent = S % (MOD - 1);
        long long factor = power_mod(p % MOD, exponent, MOD);
        answer = (answer * factor) % MOD;
    }

    cout << answer << endl;

    return 0;
}
