long long modpow(long long base, long long exp, long long mod){
    base %= mod;
    if(base < 0) base += mod;
    long long result = 1;
    while(exp > 0){
        if(exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main(){
    long long a, b, p, x;
    cin >> a >> b >> p >> x;

    long long m = p - 1;
    vector<long long> factors;
    long long temp = m;
    for(long long i = 2; i * i <= temp; i++){
        if(temp % i == 0){
            factors.push_back(i);
            while(temp % i == 0) temp /= i;
        }
    }
    if(temp > 1) factors.push_back(temp);

    long long d = m;
    if(d == 0) d = 1;

    for(long long f : factors){
        while(d % f == 0 && modpow(a, d / f, p) == 1){
            d /= f;
        }
    }
    if(d == 0) d = 1;

    long long inv_a = modpow(a, p - 2, p);
    long long inv_d = modpow(d % p, p - 2, p);

    long long M = d * p;
    long long ans = 0;

    long long pow_a = 1 % p;
    long long inv_pow_a = 1 % p;

    for(long long r = 0; r < d; r++){
        long long c_r = (b * inv_pow_a) % p;
        long long diff = ((c_r - r) % p + p) % p;
        long long t = (diff * inv_d) % p;
        long long n0 = r + d * t;

        long long cnt;
        if(n0 == 0){
            cnt = x / M;
        } else if(n0 <= x){
            cnt = (x - n0) / M + 1;
        } else {
            cnt = 0;
        }
        ans += cnt;

        pow_a = (pow_a * a) % p;
        inv_pow_a = (inv_pow_a * inv_a) % p;
    }

    cout << ans << endl;
    return 0;
