        long long target = m - 1 - s1;
        if(target >= 0){
            // binary search for largest element <= target
            auto it = upper_bound(sums2.begin(), sums2.end(), target);
            if(it != sums2.begin()){
                --it;
                long long candidate = (s1 + *it) % m;
                ans = max(ans, candidate);
            }
        }
        // case 2: use max element in sums2, if s1 + maxLast >= m
        long long candidate2 = (s1 + maxLast) % m;
