#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007;

long long fact[1005], inv_fact[1005];

long long power(long long a, long long b, long long mod) {
    long long result = 1;
    a %= mod;
    while (b > 0) {
        if (b & 1) result = result * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return result;
}

void precompute(int n) {
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = fact[i-1] * i % MOD;
    }
    inv_fact[n] = power(fact[n], MOD - 2, MOD);
    for (int i = n - 1; i >= 0; i--) {
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD;
    }
}

long long C(int n, int r) {
    if (r < 0 || r > n) return 0;
    return fact[n] * inv_fact[r] % MOD * inv_fact[n-r] % MOD;
}

int main() {
    int n, x, pos;
    cin >> n >> x >> pos;

    precompute(n);

    int lo = 0, hi = n;
    int less_cnt = 0, greater_cnt = 0;

    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (mid == pos) {
            break;
        } else if (mid < pos) {
            less_cnt++;
            lo = mid + 1;
        } else {
            greater_cnt++;
            hi = mid;
        }
    }

    long long ans = C(x - 1, less_cnt) * fact[less_cnt] % MOD;
    ans = ans * C(n - x, greater_cnt) % MOD * fact[greater_cnt] % MOD;
    ans = ans * fact[n - 1 - less_cnt - greater_cnt] % MOD;

    cout << ans << endl;

    return 0;
}
