#include <bits/stdc++.h>
using namespace std;

int main(){
    int n, t;
    cin >> n >> t;

    int H = t + 1;      // h ranges 0..t
    int V = t;          // v ranges 0..t-1 (t>=1 guarantees V>=1)

    // dp[i][y][dir][h][v]
    vector<vector<vector<vector<vector<long long>>>>> dp(
        n + 1,
        vector<vector<vector<vector<long long>>>>(
            5,
            vector<vector<vector<long long>>>(
                2,
                vector<vector<long long>>(H, vector<long long>(V, 0))
            )
        )
    );

    vector<long long> dp1(5, 0);
    for (int y = 1; y <= 4; y++) dp1[y] = 1;

    if (n == 1) {
        cout << 0 << endl;
        return 0;
    }

    // i = 2
    for (int y1 = 1; y1 <= 4; y1++) {
        for (int y2 = 1; y2 <= 4; y2++) {
            if (y2 == y1) continue;
            int dir = (y2 > y1) ? 0 : 1;
            dp[2][y2][dir][0][0] += dp1[y1];
        }
    }

    for (int i = 3; i <= n; i++) {
        for (int yprev = 1; yprev <= 4; yprev++) {
            for (int dprev = 0; dprev < 2; dprev++) {
                for (int h = 0; h < H; h++) {
                    for (int v = 0; v < V; v++) {
                        long long val = dp[i-1][yprev][dprev][h][v];
                        if (val == 0) continue;
                        for (int ycur = 1; ycur <= 4; ycur++) {
                            if (ycur == yprev) continue;
                            int dcur = (ycur > yprev) ? 0 : 1;
                            int nh = h, nv = v;
                            if (dprev == 0 && dcur == 1) nh++;
                            else if (dprev == 1 && dcur == 0) nv++;
                            if (nh >= H) continue;
                            if (nv >= V) continue;
                            dp[i][ycur][dcur][nh][nv] += val;
                        }
                    }
                }
            }
        }
    }

    long long ans = 0;
    if (n >= 2) {
        for (int y = 1; y <= 4; y++) {
            for (int dir = 0; dir < 2; dir++) {
                ans += dp[n][y][dir][t][t-1];
            }
        }
    }

    cout << ans << endl;
    return 0;
}
